/* Original procedural study geometry; never represented as a collection scan. */
window.GuanwuObjectViewer=(()=>{
 let release=null;
 function panel(o){return `<section class="object-viewer-section"><div class="section-head"><div class="section-title"><h2>换个角度，亲近器物。</h2><span>FORM STUDY · 3D</span></div></div><p>拖动转一转，看看器物的口、腹、足。示意模型帮助理解器型，具体纹饰与细节请对照上方馆方原图。</p><div class="object-viewer" data-object-viewer="${o.id}"><canvas tabindex="0" role="img" aria-label="可旋转的${o.title}器型示意。方向键旋转，加减键缩放，Home键复位。"></canvas><div class="object-viewer-label"><b>3D 器型示意</b><span>观物程序生成 · 非文物扫描或精确复原</span></div><div class="object-viewer-hint" role="status">拖拽旋转 · 双指或按钮缩放 · 方向键操作</div><div class="object-viewer-controls"><button data-viewer-control="left" aria-label="向左旋转">↶</button><button data-viewer-control="right" aria-label="向右旋转">↷</button><button data-viewer-control="in" aria-label="放大器型">＋</button><button data-viewer-control="out" aria-label="缩小器型">−</button><button data-viewer-control="reset">复位</button><button data-viewer-control="auto" aria-pressed="false">自动转动</button></div><p class="object-viewer-fallback" hidden>当前设备无法显示 3D。仍可阅读藏品档案、馆方原图与尺寸记录。</p></div><details class="object-viewer-method"><summary>模型从哪里来，能说明什么？</summary><p>这不是馆方授权的三维扫描。模型由观物用旋转曲面及简化几何生成；茶碗的高径比例在已公布高、口径或直径时参考该数值。壶的柄、嘴、壁厚、截面、釉色与纹饰均未测绘，造型仅作教学示意，不用于鉴定、复刻、尺寸测量或制造。缺少尺寸时使用通用比例。${o.fields.dimensions.value?'馆方尺寸记录：'+o.fields.dimensions.value:'这件器物尚无已整理尺寸。'}</p><p>色彩是观看辅助，不代表文物的真实釉色；有原图的条目请回看原图。获得有明确使用条件的实测模型后，可以替换此示意。</p></details></section>`}
 function mesh(o){const verts=[],norms=[];function triangle(a,b,c,na,nb,nc){verts.push(...a,...b,...c);norms.push(...na,...nb,...nc)}
  function lathe(profile,n=80,xOffset=0,yOffset=0){for(let j=0;j<profile.length-1;j++){const [r0,y0]=profile[j],[r1,y1]=profile[j+1],dr=r1-r0,dy=y1-y0,len=Math.hypot(dr,dy)||1;for(let i=0;i<n;i++){const a=i/n*Math.PI*2,b=(i+1)/n*Math.PI*2;const p=(r,y,t)=>[xOffset+r*Math.cos(t),yOffset+y,r*Math.sin(t)],nm=t=>[dy/len*Math.cos(t),-dr/len,dy/len*Math.sin(t)];triangle(p(r0,y0,a),p(r1,y1,a),p(r1,y1,b),nm(a),nm(a),nm(b));triangle(p(r0,y0,a),p(r1,y1,b),p(r0,y0,b),nm(a),nm(b),nm(b))}}}
  function tube(path,radius,segments=20){for(let j=0;j<path.length-1;j++){const a=path[j],b=path[j+1],dx=b[0]-a[0],dy=b[1]-a[1],len=Math.hypot(dx,dy)||1;const norm=t=>[-dy/len*Math.cos(t),dx/len*Math.cos(t),Math.sin(t)],p=(c,t)=>{const n=norm(t);return c.map((v,i)=>v+radius*n[i])};for(let i=0;i<segments;i++){const t=i/segments*Math.PI*2,u=(i+1)/segments*Math.PI*2;triangle(p(a,t),p(b,t),p(b,u),norm(t),norm(t),norm(u));triangle(p(a,t),p(b,u),p(a,u),norm(t),norm(u),norm(u))}}}
  if(o.objectType==='茶壶'){
   const facets=o.id==='tea-dpm-227616'?6:80;
   lathe([[0,-.66],[.3,-.66],[.34,-.6],[.6,-.55],[.75,-.32],[.79,.05],[.64,.38],[.37,.53],[.37,.58],[.31,.58],[.31,.48],[.58,.32],[.69,.02],[.63,-.3],[.48,-.46],[0,-.46]],facets);
   lathe([[0,.61],[.1,.61],[.12,.65],[.08,.72],[0,.74]],32);lathe([[0,.57],[.36,.57],[.4,.55],[.42,.58],[.3,.63],[0,.63]],facets);
   const handle=[];for(let i=0;i<=42;i++){const t=-Math.PI*.55+i/42*Math.PI*1.1;handle.push([-.67-.48*Math.cos(t),.01+.49*Math.sin(t),0])}tube(handle,.075);
   tube([[.57,-.21,0],[.82,-.1,0],[1.02,.14,0],[1.16,.38,0],[1.27,.48,0]],.11);
  }else{
   const d=o.fields.dimensions.value||'',h=d.match(/高\s*([\d.]+)/),diam=d.match(/(?:口径|直径)\s*([\d.]+)/),height=h&&diam?Math.min(1.5,Math.max(.45,2*Number(h[1])/Number(diam[1]))):.94;
   const y=-height/2;lathe([[0,y],[.3,y],[.34,y+.06],[.33,y+.14],[.44,y+.19],[.6,y+height*.38],[.8,y+height*.65],[.98,y+height*.95],[1,y+height],[.96,y+height+.012],[.92,y+height*.94],[.74,y+height*.64],[.53,y+height*.36],[.33,y+.23],[0,y+.2]]);
  }return {positions:new Float32Array(verts),normals:new Float32Array(norms)};
 }
 function mount(route){if(release){release();release=null}if(!route.startsWith('object/'))return;const host=document.querySelector('[data-object-viewer]');if(!host)return;const o=GuanwuKnowledge.get(host.dataset.objectViewer),canvas=host.querySelector('canvas');let gl;try{gl=canvas.getContext('webgl',{alpha:false,antialias:true,preserveDrawingBuffer:true})}catch{}if(!gl){host.querySelector('.object-viewer-fallback').hidden=false;host.querySelector('.object-viewer-hint').textContent='3D 暂不可用';canvas.hidden=true;return}
  const shader=(type,source)=>{const s=gl.createShader(type);gl.shaderSource(s,source);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error('shader');return s};
  const program=gl.createProgram();let vs,fs;
  try{vs=shader(gl.VERTEX_SHADER,'attribute vec3 position; attribute vec3 normal; uniform float yaw; uniform float pitch; uniform float zoom; uniform float aspect; varying vec3 N; varying vec3 P; vec3 rotate(vec3 p){p=vec3(cos(yaw)*p.x+sin(yaw)*p.z,p.y,-sin(yaw)*p.x+cos(yaw)*p.z);return vec3(p.x,cos(pitch)*p.y-sin(pitch)*p.z,sin(pitch)*p.y+cos(pitch)*p.z);} void main(){vec3 p=rotate(position)*zoom;N=rotate(normal);P=p;p.z-=4.4;float f=2.4142;gl_Position=vec4(p.x*f/aspect,p.y*f,-1.004*p.z-.2004,-p.z);}');fs=shader(gl.FRAGMENT_SHADER,'precision mediump float; varying vec3 N; varying vec3 P; uniform vec3 clay; void main(){vec3 n=normalize(N);vec3 light=normalize(vec3(-2.,3.,4.));float d=max(0.,dot(n,light));vec3 eye=normalize(vec3(0.,0.,4.4)-P);float spec=pow(max(0.,dot(n,normalize(light+eye))),48.);vec3 base=clay*(.27+.7*d)+vec3(.38)*spec;float rim=pow(1.-max(0.,dot(n,eye)),3.);gl_FragColor=vec4(base+rim*.055,1.);}');gl.attachShader(program,vs);gl.attachShader(program,fs);gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error('link')}catch{host.querySelector('.object-viewer-fallback').hidden=false;canvas.hidden=true;return}
  gl.useProgram(program);const geometry=mesh(o),buffers=[];
  for(const [name,values] of [['position',geometry.positions],['normal',geometry.normals]]){const b=gl.createBuffer();buffers.push(b);gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,values,gl.STATIC_DRAW);const attr=gl.getAttribLocation(program,name);gl.enableVertexAttribArray(attr);gl.vertexAttribPointer(attr,3,gl.FLOAT,false,0,0)}
  const uniforms=Object.fromEntries(['yaw','pitch','zoom','aspect','clay'].map(k=>[k,gl.getUniformLocation(program,k)]));gl.enable(gl.DEPTH_TEST);gl.clearColor(.91,.89,.84,1);
  let yaw=.35,pitch=.37,zoom=1,frame=0,auto=false,visible=true,disposed=false,last=0,pointers=new Map(),pinch=null;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
  const color=/紫砂/.test(o.title)?[.48,.27,.16]:/青花/.test(o.title)?[.73,.77,.73]:[.27,.22,.15];gl.uniform3fv(uniforms.clay,color);
  function draw(){if(disposed||gl.isContextLost())return;gl.viewport(0,0,canvas.width,canvas.height);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.uniform1f(uniforms.yaw,yaw);gl.uniform1f(uniforms.pitch,pitch);gl.uniform1f(uniforms.zoom,zoom);gl.uniform1f(uniforms.aspect,canvas.width/canvas.height);gl.drawArrays(gl.TRIANGLES,0,geometry.positions.length/3);canvas.dataset.yaw=yaw.toFixed(3);canvas.dataset.zoom=zoom.toFixed(3);canvas.dataset.rendered='true'}
  function animate(t){frame=0;if(!auto||!visible||disposed||document.hidden)return;const dt=Math.min((t-last)/1000,.05);last=t;yaw+=dt*.3;draw();frame=requestAnimationFrame(animate)}
  function pause(){auto=false;cancelAnimationFrame(frame);frame=0;const b=host.querySelector('[data-viewer-control="auto"]');b.textContent='自动转动';b.setAttribute('aria-pressed','false')}
  function resize(){const r=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,Math.round(r.width*dpr));canvas.height=Math.max(1,Math.round(r.height*dpr));draw()}
  const ro=new ResizeObserver(resize);ro.observe(canvas);const io=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(!visible){cancelAnimationFrame(frame);frame=0}else if(auto&&!frame){last=performance.now();frame=requestAnimationFrame(animate)}});io.observe(host);
  canvas.onpointerdown=ev=>{pause();pointers.set(ev.pointerId,{x:ev.clientX,y:ev.clientY});canvas.setPointerCapture(ev.pointerId);canvas.classList.add('dragging');if(pointers.size===2){const p=[...pointers.values()];pinch=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y)}};
  canvas.onpointermove=ev=>{const prev=pointers.get(ev.pointerId);if(!prev)return;pointers.set(ev.pointerId,{x:ev.clientX,y:ev.clientY});if(pointers.size===2){const p=[...pointers.values()],distance=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y);if(pinch)zoom=Math.max(.65,Math.min(1.8,zoom*distance/pinch));pinch=distance}else{yaw+=(ev.clientX-prev.x)*.009;pitch=Math.max(-.7,Math.min(1.25,pitch+(ev.clientY-prev.y)*.007))}draw()};
  const up=ev=>{pointers.delete(ev.pointerId);pinch=null;if(!pointers.size)canvas.classList.remove('dragging')};canvas.onpointerup=up;canvas.onpointercancel=up;canvas.onlostpointercapture=up;
  function control(name){if(name!=='auto')pause();if(name==='left')yaw-=.2;if(name==='right')yaw+=.2;if(name==='in')zoom=Math.min(1.8,zoom+.12);if(name==='out')zoom=Math.max(.65,zoom-.12);if(name==='reset'){yaw=.35;pitch=.37;zoom=1}if(name==='auto'){if(auto)pause();else{auto=true;const b=host.querySelector('[data-viewer-control="auto"]');b.textContent='暂停转动';b.setAttribute('aria-pressed','true');last=performance.now();frame=requestAnimationFrame(animate);if(reduced)host.querySelector('.object-viewer-hint').textContent='已按你的操作开启转动，可随时暂停。'}}draw()}
  host.querySelectorAll('[data-viewer-control]').forEach(b=>b.onclick=()=>control(b.dataset.viewerControl));canvas.onkeydown=ev=>{const map={ArrowLeft:'left',ArrowRight:'right','+':'in','=':'in','-':'out',Home:'reset'};if(map[ev.key]){ev.preventDefault();control(map[ev.key])}if(ev.key==='ArrowUp'||ev.key==='ArrowDown'){ev.preventDefault();pause();pitch=Math.max(-.7,Math.min(1.25,pitch+(ev.key==='ArrowUp'?-.15:.15)));draw()}};
  const visibility=()=>{if(document.hidden){cancelAnimationFrame(frame);frame=0}else if(auto&&visible&&!frame){last=performance.now();frame=requestAnimationFrame(animate)}};document.addEventListener('visibilitychange',visibility);
  canvas.addEventListener('webglcontextlost',ev=>{ev.preventDefault();pause();host.querySelector('.object-viewer-fallback').hidden=false});canvas.addEventListener('webglcontextrestored',()=>mount(route));resize();
  release=()=>{disposed=true;cancelAnimationFrame(frame);ro.disconnect();io.disconnect();document.removeEventListener('visibilitychange',visibility);for(const b of buffers)gl.deleteBuffer(b);gl.deleteProgram(program);gl.deleteShader(vs);gl.deleteShader(fs);gl.getExtension('WEBGL_lose_context')?.loseContext()};
 }
 return {panel,mount,mesh};
})();
